import{o as t,c as e,a}from"./app.fcda16e3.js";const n='{"title":"laravel发邮箱","description":"","frontmatter":{},"headers":[{"level":2,"title":"基础使用","slug":"基础使用"}],"relativePath":"components/mapLocus.md","lastUpdated":1690536970445}',l={},o=a('<h1 id="laravel发邮箱"><a class="header-anchor" href="#laravel发邮箱" aria-hidden="true">#</a> laravel发邮箱</h1><h2 id="基础使用"><a class="header-anchor" href="#基础使用" aria-hidden="true">#</a> 基础使用</h2><p>1.在 Laravel 中发送邮件可以使用内置的 Mail 类。首先需要在 .env 文件中配置邮件服务商的信息</p><div class="language-"><pre><code>MAIL_MAILER=smtp\nMAIL_HOST=smtp.qq.com\nMAIL_PORT=465\nMAIL_USERNAME=你的QQ邮箱账号\nMAIL_PASSWORD=你的QQ邮箱授权码\nMAIL_ENCRYPTION=ssl\nMAIL_FROM_ADDRESS=发件人邮箱地址\nMAIL_FROM_NAME=发件人名称\n\n</code></pre></div><p>2.控制器方法</p><div class="language-"><pre><code>use Illuminate\\Support\\Facades\\Mail;\n public function email(Request $request, $id)\n    {\n  \n        $email = ;\n        $code = rand(1000, 9999);\n \n        //使用blade模板发送(引用的模板)\n        Mail::send(&#39;admin.emails.email&#39;, [&#39;code&#39; =&gt; $code], function ($message) use ($email) {\n            $message-&gt;to($email)-&gt;subject(&#39;水蜜桃的夏天&#39;);\n        });\n\n        if (Mail::failures()) {\n            return [&quot;code&quot; =&gt; 0, &quot;msg&quot; =&gt; &quot;error&quot;];\n        }\n        return [&quot;code&quot; =&gt; 1, &quot;msg&quot; =&gt; &quot;success&quot;];\n    }\n\n</code></pre></div><p>3.blade模板</p><div class="language-"><pre><code>&lt;!DOCTYPE html&gt;\n&lt;html&gt;\n&lt;head&gt;\n\t&lt;title&gt;邮箱测试模板&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n\t&lt;h1&gt;您的验证码是，{{$code}}！&lt;/h1&gt;\n\t&lt;p&gt;请在一分钟内注册，啦啦啦啦啦啦啦！！！！&lt;/p&gt;\n&lt;/body&gt;\n&lt;/html&gt;\n</code></pre></div><div class="warning custom-block"><p class="custom-block-title">注意事项</p><ul><li>qq邮箱授权码申请</li></ul></div><p><strong>如遇到其他问题，建议您仔细阅读uniapp的 <a href="https://uniapp.dcloud.io/component/map" target="_blank" rel="noopener noreferrer">Map说明</a></strong></p><p><strong>如您有其他地图方面的定制开发，您可以联系作者</strong></p>',11);l.render=function(a,n,l,r,s,d){return t(),e("div",null,[o])};export default l;export{n as __pageData};
